js.text:

function grid$dmkhtest(f){
  this.constructor(f);
}
grid$dmkhtest.prototype = new DirEvent();
grid$dmkhtest.prototype.afterInitFields = function(){
  var p = this._dir;
}

var tbl;
grid$dmkhtest.prototype.afterInit = function(){
  var p = this._dir;

  var s = '<button class="btn-action btn-action-v1" id="btnViewTree"><img src="../Images/ic_calendar.png" class="icon-bottom-toolbar"/></button>'
  $("#content").append(s);
  $("#btnViewTree").click(function () {
    var f = $("#tree_form_region");
    if(f.css("display") && f.css("display") != "none"){
      var s = "";
      var chk = $(".tree-check:checked")
      chk.each(function () {
          if (!$(this).closest('li').hasClass("tree-hassub"))
            s += "," + tbl[$(this).attr("rowid")][2];
      });
      alert(s.substring(1))
    }
    else if(tbl)
      $("#tree_form_region").show(150);
    else
      p.request('viewtree', 'GetTable', null, loadTree);
  });
}
function loadTree(p, d){
  var d = new DataTable(d);
  tbl = d.obj.Rows;

  var mgTop = $(p.find(".table-bottom")[0]).css("top");

  var s = '<div class="tree-form" id="tree_form_region" style="top: ' + mgTop + '; margin-top: 2px; display: none;"><div class="header-tree">Cây vùng, khu vực</div><button type="button" id="cancel_tree_region" class="btn-close-form btn-close-tree" data-dismiss="modal" aria-label="Close"><span class="icon-close-form">✖</span></button><div class="tree-group" id="tree_region"></div></div>';
  $("#content").append(s);
  $("#tree_form_region").show(150);
  $("#cancel_tree_region").click(function () {
      $("#tree_form_region").hide(150);
  });


  var lastLevel = -1, maxLevel = 1;
  s = '<ul class="tree-main">@@L001';  
  for(var i = 0; i < tbl.length; i ++){
    var ilevel = parseInt(tbl[i][0]);
    if(ilevel > maxLevel) maxLevel = ilevel;
    var xlevel = ("000" + ilevel).substr(-3);
    var xlevel2 = ("000" + (ilevel + 1)).substr(-3);
    var tmp = '<div class="checkbox node-tree"><label><input class="tree-check" type="checkbox" rowid="' + i + '"><span class="checkbox-material checkbox-tree"><span class="check"></span></span></label></div><span class="tree-collaps">' + tbl[i][1] + '</span>@@L' + xlevel2 + '</li>@@L' + xlevel;

    if(lastLevel == -1 || ilevel == lastLevel){
      s = s.replace("@@L" + xlevel2, "");
      tmp = '<li ' + (xlevel == "001" ? ' class="tree-root"' : '') + '>' + tmp;
      s = s.replace("@@L" + xlevel, tmp);
    }
    else if(ilevel > lastLevel){
      tmp = '<ul style="display: none;"><li>' + tmp + '</ul>';
      s = s.replace("@@L" + xlevel, tmp);
    }
    else{
      for(var x = ilevel + 1; x <= lastLevel + 1; x ++)
        s = s.replace("@@L" + ("000" + x).substr(-3), "");
      s = s.replace("@@L" + xlevel, '<li>' + tmp);
    }
    lastLevel = ilevel;
  }
  s += '</ul>';
  for(var i = 1; i <= maxLevel + 1; i ++)
    s = s.replace("@@L" + ("000" + i).substr(-3), "");

  $("#tree_region").append(s);

  $('.tree-group li:has(ul)').addClass('tree-hassub');
  $('.tree-group .tree-collaps').click(function () {
      $(this).parent().children().toggle();
      $(this).toggle();

      var chk = $(this).parent().find('.checkbox:eq(0)');
      chk.toggle();

      var c = chk.parent().find("ul:eq(0)").css("display");
      if (c) {
          if(c == "none")
              chk.removeClass("node-tree-expand")
          else
              chk.addClass("node-tree-expand")

      }
  });
  $('.tree-group .tree-check').change(function () {
      var obj = $(this);
      var flag = this.checked;
      obj.parent().find(".check").removeClass('check-rdo')

      var parentLi = obj.closest('li');
      parentLi.find('.tree-check:gt(0)').prop('checked', flag);
      parentLi.find(".check").removeClass('check-rdo');

      treeCheckParent(parentLi);
  });
}

function treeCheckParent(obj) {
  var curUl = obj.closest('ul');
  var curli = curUl.closest('li');
  var hasUncheck = false;
  var hasCheck = false;
  curUl.find('li').each(function () {
      if (!$(this).find('.tree-check').prop('checked'))
          hasUncheck = true;
      else
          hasCheck = true;
  });
  if (hasUncheck) {
      curli.find('.check:eq(0)').addClass('check-rdo');
      curli.find('.tree-check:eq(0)').prop('checked', hasCheck);
  }
  else {
      curli.find('.check:eq(0)').removeClass("check-rdo");
      curli.find('.tree-check:eq(0)').prop('checked', hasCheck);
  }
  if (!curli.hasClass("tree-root") && !curUl.hasClass("tree-main"))
      treeCheckParent(curli);
}
